"""Small public-format fixtures without proprietary executable content."""

import io
from base64 import b64decode
import struct
import uuid
import zlib
import zipfile


def appimage(payload=b"fixture"):
    # GNU as/ld built a static x86_64 exit stub, with the type-2 marker added.
    runtime = zlib.decompress(b64decode(
        "eNqrd/VxY2JkZHD0ZGIAASYGOwZGEEPAAcyHkAwMCgIMcODAYAFU58DADCRBalkYkIEDCr0ByoPRDFBzQPpYkfgw+2A0J1SYE03fKBgFo2AU"
        "jIJRMApGwSgYBaNgFIyCUTAKSAc7bICE4X9+Vga94ozikqKSxCQGvZLUihIqmc8N7euzMaD389H69wyIcQF0PjMWczmh+gUJ6AcADD4O4w=="
    ))
    # Generated by squashfs-tools 4.5.1 from a tiny public AppRun shell fixture.
    squashfs = zlib.decompress(b64decode(
        "eNrLKC4sZmKAAQiLkUGQIYCJkYEFyFaByhyH0vuh9H8oKITy50PpnWjyyor6SZl5+sUZXKkVmSUKBlw6DBW3kpMqTp9gYJGKC9/s0MOi8I+f"
        "RcHQkSMtxSXo8BEGRoUosY6ZjRIMWz04n0mAVCc0MLhpnD1y4NSDiACBkFnsDBw6TPEsDcjWjYJRMApGwSgYBaNgFIyCUTAKRsEoGAWjAA8AALoVNIY="
    ))
    return runtime + squashfs + payload


def msi(*, architecture="x64", installer=True):
    """Build an independently readable MSI Property database with real mini streams."""
    end, free, fat = 0xfffffffe, 0xffffffff, 0xfffffffd
    header = bytearray(512)
    header[:8] = bytes.fromhex("d0cf11e0a1b11ae1")
    struct.pack_into("<HHHHH", header, 24, 0x3e, 3, 0xfffe, 9, 6)
    struct.pack_into("<IIIIIIIII", header, 40, 0, 1, 1, 0, 4096, 3, 1, end, 0)
    struct.pack_into("<109I", header, 76, 0, *([free] * 108))
    template = (architecture + ";1033\0").encode()
    prop = struct.pack("<II", 30, len(template)) + template
    prop += b"\0" * (-len(prop) % 4)
    section = struct.pack("<IIIIII", 32 + len(prop), 2, 1, 24, 7, 32)
    section += struct.pack("<IhH", 2, 1252, 0) + prop
    summary = struct.pack("<HHI16sI", 0xfffe, 0, 0, b"\0" * 16, 1)
    summary += uuid.UUID("F29F85E0-4FF9-1068-AB91-08002B27B3D9").bytes_le + struct.pack("<I", 48) + section
    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz._"

    def encoded(name):
        output = "\u4840"
        for offset in range(0, len(name), 2):
            first = alphabet.index(name[offset])
            if offset + 1 == len(name):
                output += chr(0x4800 + first)
            else:
                output += chr(0x3800 + first + 64 * alphabet.index(name[offset + 1]))
        return output

    strings = [b"Property", b"Value", b"ProductName", b"M04 fixture", b"ProductVersion", b"1.0.0",
               b"ProductCode", b"{12345678-1234-1234-1234-123456789012}"]
    pool = b"\0" * 4 + b"".join(struct.pack("<HH", len(value), 1) for value in strings)
    columns = struct.pack("<8H", 1, 1, 0x8001, 0x8002, 1, 2, 0xa948, 0x9d00)
    values = [pool, b"".join(strings), struct.pack("<H", 1), columns,
              struct.pack("<6H", 3, 5, 7, 4, 6, 8), summary]
    streams = [encoded(name) for name in ("_StringPool", "_StringData", "_Tables", "_Columns", "Property")]
    streams.append("\x05SummaryInformation")
    directory = bytearray(1024)

    def entry(index, name, kind, first, size, right=free, child=free, clsid=None):
        raw = bytearray(128)
        text = (name + "\0").encode("utf-16le")
        raw[:len(text)] = text
        struct.pack_into("<HBBIII", raw, 64, len(text), kind, 1, free, right, child)
        if clsid:
            raw[80:96] = uuid.UUID(clsid).bytes_le
        struct.pack_into("<IQ", raw, 116, first, size)
        directory[index * 128:(index + 1) * 128] = raw

    table = [free] * 128
    table[0:4] = [fat, 2, end, end]
    mini_table = [free] * 128
    data = bytearray()
    for index, (name, content) in enumerate(zip(streams, values)):
        first = len(data) // 64
        sectors = (len(content) + 63) // 64
        entry(index + 1, name, 2, first, len(content), right=index + 2 if index < 5 else free)
        for sector in range(first, first + sectors):
            mini_table[sector] = sector + 1 if sector < first + sectors - 1 else end
        data.extend(content.ljust(sectors * 64, b"\0"))
    entry(0, "Root Entry", 5, 4, len(data), child=1,
          clsid="000C1084-0000-0000-C000-000000000046" if installer else None)
    for sector in range(4, 4 + (len(data) + 511) // 512):
        table[sector] = sector + 1 if sector < 3 + (len(data) + 511) // 512 else end
    return (bytes(header) + struct.pack("<128I", *table) + directory + struct.pack("<128I", *mini_table)
            + data.ljust((len(data) + 511) // 512 * 512, b"\0"))


def winetricks_zip(script=b"#!/bin/sh\nexit 0\n"):
    output = io.BytesIO()
    with zipfile.ZipFile(output, "w") as archive:
        archive.writestr("winetricks-test/src/winetricks", script)
    return output.getvalue()
